+/**
+ * 90 度回った親の中で掴んだ時点の配置。親の座標の y 軸は画面の左を向く。
+ */
+const GrabbedInTurned: GrabbedPlacement = {
+  placement: GrabbedAt,
+  parentRotation: 90,
+};
+
+/** 90 度回った今の親へそのまま落とす。 */
+const Turned: ParentCoordinates = {
+  name: "frame",
+  shift: { x: 0, y: 0 },
+  rotation: 90,
+};
+
+test("90 度回った親の中で画面上の左へ運ぶと、書かれる座標は親の座標で y が運んだ量だけ増える", () => {
+  // 運んだ量を親の向きへ戻さないと x が 7 減る
+  const dropped = RepositionTarget.create(
+    GrabbedInTurned,
+    { x: -7, y: 0 },
+    Turned,
+  );
+
+  expect(dropped.to).toEqual({
+    parentName: "frame",
+    placement: { mode: "absolute", x: 40, y: 31 },
+  });
+});
+
+test("90 度回った親の中で画面上の左へ運ぶと、見た目のずらし量も親の向きへ戻した量になる", () => {
+  // ずらし量は親と一緒に回って効くので、戻さないと画面上では上へずれて見える
+  const dropped = RepositionTarget.create(
+    GrabbedInTurned,
+    { x: -7, y: 0 },
+    Turned,
+  );
+
+  expect(dropped.offset).toEqual({ x: 0, y: 7 });
+});
+
+test("90 度回った親の中で、親を決めずに求めたずらし量も親の向きへ戻した量になる", () => {
+  // 落とせる場所の外へ出た瞬間にずれる向きが変わってはいけないので、`create` と同じ戻し方
+  expect(
+    RepositionTarget.carriedOffset(GrabbedInTurned, { x: -7, y: 0 }),
+  ).toEqual({ x: 0, y: 7 });
+});
+
+test("30 度回った親の中で割り切れない量を運んでも、書かれる座標とずらし量は同じ丸めた行き先から出る", () => {
+  // 親の向きへ戻した量は (19.12, -23.54)。丸めた行き先 (59, 0) から逆算すると (19, -24)
+  const dropped = RepositionTarget.create(
+    { placement: GrabbedAt, parentRotation: 30 },
+    { x: 28.33, y: -10.83 },
+    { name: "home", shift: { x: 0, y: 0 }, rotation: 30 },
+  );
+
+  expect([dropped.to.placement, dropped.offset]).toEqual([
+    { mode: "absolute", x: 59, y: 0 },
+    { x: 19, y: -24 },
+  ]);
+});
+
+test("90 度回った親から回っていない親へ付け替えると、書かれる座標は親の座標の原点と向きを直した値になる", () => {
+  /*
+   * 今の親の座標の原点は、落とし先の座標で (250, 0)。運んだ先 (10, 17) を 90 度回すと
+   * (-17, 10) で、原点の位置を足して (233, 10)。向きを直さないと (260, 17) になる
+   */
+  const dropped = RepositionTarget.create(
+    { placement: { mode: "absolute", x: 10, y: 10 }, parentRotation: 90 },
+    { x: -7, y: 0 },
+    { name: "home", shift: { x: 250, y: 0 }, rotation: 0 },
+  );
+
+  expect(dropped.to).toEqual({
+    parentName: "home",
+    placement: { mode: "absolute", x: 233, y: 10 },
+  });
+});
+
+test("回っていない親から 90 度回った親へ付け替えると、書かれる座標は落とし先の向きで測った値になる", () => {
+  /*
+   * 今の親の座標の原点は、落とし先の座標で (0, 250)。運んだ先 (200, 30) を -90 度回すと
+   * (30, -200) で、原点の位置を足して (30, 50)。向きを直さないと (200, 280) になる
+   */
+  const dropped = RepositionTarget.create(
+    { placement: { mode: "absolute", x: 20, y: 150 }, parentRotation: 0 },
+    { x: 180, y: -120 },
+    { name: "frame", shift: { x: 0, y: 250 }, rotation: 90 },
+  );
+
+  expect(dropped.to).toEqual({
+    parentName: "frame",
+    placement: { mode: "absolute", x: 30, y: 50 },
+  });
+});
+
+test("360 度回った親の中では、回っていない親の中と同じ座標が書かれる", () => {
