+    { placement: GrabbedAt, parentRotation: 360 },
+    { x: 30, y: -12 },
+    { name: "home", shift: { x: 0, y: 0 }, rotation: 360 },
+  );
+
+  expect(dropped.to).toEqual({
+    parentName: "home",
+    placement: { mode: "absolute", x: 70, y: 12 },
+  });
+});

